<template>
  <teleport to="body"><div class="fixed inset-0 z-[70] bg-black/45 p-4 flex items-center justify-center" @click.self="requestClose"><section class="w-full max-w-5xl max-h-[92vh] overflow-hidden bg-surface-elevated border border-border rounded-panel shadow-overlay flex flex-col" role="dialog" aria-modal="true" aria-labelledby="document-composer-title" data-testid="client-document-composer">
    <header class="p-6 border-b border-border-muted flex items-start justify-between gap-4"><div><p class="type-overline text-ink-muted">Client document</p><h2 id="document-composer-title" class="text-h2 font-semibold text-ink mt-1">{{ finalised ? 'Document Finalised' : (document ? 'Edit Document' : 'Create Document') }}</h2><p class="text-body-sm text-ink-secondary mt-1">{{ finalised ? 'The PDF is read-only and safely stored with this client.' : 'Drafts are saved to Helio. Only completed clinical session notes can be selected as source material.' }}</p></div><button type="button" aria-label="Close document composer" class="text-ink-muted hover:text-ink" @click="requestClose">✕</button></header>
    <div class="flex-1 overflow-auto p-6">
      <div v-if="finalised" class="max-w-2xl mx-auto py-10" data-testid="document-finalised-success"><div class="rounded-panel border border-state-success/20 bg-state-success-surface p-6"><p class="text-h3 font-semibold text-state-success">✓ PDF finalised and saved</p><p class="text-body-sm text-ink-secondary mt-2"><strong>{{ currentDocument.title }}</strong> is saved to this client's Documents area{{ currentDocument.originalFilename ? ` as ${currentDocument.originalFilename}` : '' }}.</p><p class="text-caption text-ink-muted mt-3">Finalised {{ formatDateTime(currentDocument.finalizedAt) }} · This version is read-only.</p></div><div class="mt-6 flex flex-wrap gap-2"><button type="button" class="button-primary" @click="downloadFinalised">Download PDF</button><button type="button" class="button-secondary" @click="$emit('show-documents')">View Client Documents</button><button type="button" class="button-secondary" @click="requestClose">Close</button></div></div>
      <template v-else><div v-if="loading" class="py-16 text-center text-ink-muted">Loading document workspace…</div><div v-else class="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_300px] gap-6"><div class="space-y-5">
        <label class="block"><span class="text-caption font-semibold text-ink">Title</span><input v-model="form.title" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" placeholder="e.g. Clinical summary – August 2026" /></label>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4"><label class="block"><span class="text-caption font-semibold text-ink">Document type</span><select v-model="form.documentType" class="mt-1 w-full p-3 border border-border rounded-control bg-surface"><option value="clinical_summary">Clinical summary</option><option value="progress_report">Progress report</option><option value="care_letter">Care letter</option><option value="other">Other</option></select></label><label class="block"><span class="text-caption font-semibold text-ink">Recipient</span><input v-model="form.recipient" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" placeholder="Optional" /></label></div>
        <label class="block"><span class="text-caption font-semibold text-ink">Purpose</span><input v-model="form.purpose" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" placeholder="Why this document is being prepared" /></label>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4"><label class="block"><span class="text-caption font-semibold text-ink">Period start</span><input v-model="form.periodStart" type="date" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" /></label><label class="block"><span class="text-caption font-semibold text-ink">Period end</span><input v-model="form.periodEnd" type="date" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" /></label></div>
        <label class="block"><span class="flex items-center justify-between gap-3"><span class="text-caption font-semibold text-ink">Document body</span><span v-if="selectedSourceIds.length" class="text-caption text-ink-muted">Sources: {{ selectedSourceIds.length }} session{{ selectedSourceIds.length === 1 ? '' : 's' }}</span></span><textarea v-model="form.body" rows="16" class="mt-1 w-full p-4 border border-border rounded-control bg-surface resize-y" placeholder="Write the document here. You can add selected session notes from the source panel." /></label>
      </div><aside class="lg:max-h-[60vh] flex flex-col min-h-0 border border-border rounded-panel bg-surface-subtle overflow-hidden" data-testid="clinical-source-panel"><div class="p-4 border-b border-border-muted"><div class="flex items-center justify-between gap-2"><h3 class="text-body-sm font-semibold text-ink">Clinical sources</h3><span class="text-caption text-ink-muted">{{ selectedSourceIds.length }} selected</span></div><p class="text-caption text-ink-muted mt-1">Private reflections and supervision material are not available here.</p><input v-model="sourceQuery" type="search" class="mt-3 w-full p-2.5 border border-border rounded-control bg-surface text-body-sm" placeholder="Search session notes…" aria-label="Search clinical sources" @input="resetSourceWindow" /><label v-if="visibleSources.length" class="mt-3 flex items-center gap-2 text-caption text-ink-secondary"><input type="checkbox" :checked="allVisibleSelected" @change="toggleAllVisible" /> Select all shown</label></div><div class="flex-1 min-h-0 overflow-y-auto p-2 space-y-1" data-testid="clinical-source-list"><div v-if="sources.length === 0" class="p-3 text-body-sm text-ink-muted">No completed session notes are available for this client.</div><div v-else-if="filteredSources.length === 0" class="p-3 text-body-sm text-ink-muted">No session notes match your search.</div><div v-for="source in visibleSources" :key="source.id" class="border border-border rounded-control bg-surface"><div class="flex items-center gap-2 p-2.5"><input v-model="selectedSourceIds" type="checkbox" :value="source.id" :aria-label="`Select session ${formatDate(source.occurredAt)}`" /><button type="button" class="min-w-0 flex-1 text-left" @click="toggleSourcePreview(source.id)"><strong class="block text-body-sm text-ink">{{ formatDate(source.occurredAt) }}</strong><span class="block text-caption text-ink-muted">Clinical session note · v{{ source.version }}</span></button><span v-if="addedSourceIds.includes(source.id)" class="text-caption text-state-success font-semibold">Added</span><button type="button" class="text-caption text-ink-muted hover:text-ink px-1" :aria-expanded="expandedSourceId === source.id" :aria-label="`${expandedSourceId === source.id ? 'Hide' : 'Preview'} session note ${formatDate(source.occurredAt)}`" @click="toggleSourcePreview(source.id)">{{ expandedSourceId === source.id ? 'Hide' : 'Preview' }}</button></div><div v-if="expandedSourceId === source.id" class="px-3 pb-3 text-body-sm text-ink-secondary whitespace-pre-wrap border-t border-border-muted pt-3">{{ source.notes || 'No note text' }}</div></div><div v-if="filteredSources.length" class="px-2 py-3 text-center"><p class="text-caption text-ink-muted">Showing {{ visibleSources.length }} of {{ filteredSources.length }} session{{ filteredSources.length === 1 ? '' : 's' }}</p><button v-if="hasMoreSources" type="button" class="mt-2 text-body-sm font-semibold text-action-link hover:underline" data-testid="load-more-clinical-sources" @click="loadMoreSources">Load {{ nextSourceCount }} more</button></div></div><div class="p-3 border-t border-border-muted bg-surface-elevated"><button type="button" class="button-secondary w-full" :disabled="addableSelectedSources.length === 0" @click="appendSources">{{ addableSelectedSources.length ? `Add ${addableSelectedSources.length} selected note${addableSelectedSources.length === 1 ? '' : 's'} to draft` : (selectedSources.length ? 'Selected notes already added' : 'Add selected notes to draft') }}</button></div></aside></div><div v-if="error" class="mt-5 p-4 rounded-control bg-state-danger/10 text-state-danger" role="alert">{{ error }}</div></template>
    </div>
    <footer v-if="!finalised" class="p-6 border-t border-border-muted flex flex-wrap items-center justify-between gap-4"><p class="text-caption" :class="dirty ? 'text-state-warning' : 'text-ink-muted'">{{ dirty ? 'Unsaved changes' : saveMessage }}</p><div class="flex flex-wrap gap-2"><button type="button" class="button-secondary" :disabled="saving" @click="requestClose">Close</button><button type="button" class="button-secondary" :disabled="saving || !form.title.trim()" @click="previewDocument">{{ saving && action === 'preview' ? 'Preparing…' : 'Preview PDF' }}</button><button type="button" class="button-secondary" :disabled="saving || !form.title.trim()" @click="saveDraft">{{ saving && action === 'save' ? 'Saving…' : 'Save Draft' }}</button><button type="button" class="button-primary" :disabled="saving || !form.title.trim() || !form.body.trim()" @click="finaliseDocument">{{ saving && action === 'finalise' ? 'Finalising…' : 'Finalise PDF' }}</button></div></footer>
    <div v-if="previewUrl" class="absolute inset-4 z-10 rounded-panel bg-surface-elevated border border-border shadow-overlay flex flex-col" data-testid="document-pdf-preview"><header class="p-4 border-b border-border-muted flex items-center justify-between gap-3"><div><h3 class="font-semibold text-ink">PDF preview</h3><p class="text-caption text-ink-muted">This is generated by the same renderer used for the final PDF.</p></div><div class="flex gap-2"><button type="button" class="button-secondary" @click="printPreview">Print</button><button type="button" class="button-secondary" @click="closePreview">Back to document</button></div></header><iframe ref="previewFrame" :src="previewUrl" title="PDF preview" class="w-full flex-1 bg-white rounded-b-panel"></iframe></div>
  </section></div></teleport>
</template>
<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue';
import { createClientDocumentDraft,downloadClientDocument,finaliseClientDocument,listDocumentSourceSessions,previewClientDocument,saveClientDocumentDraft } from '../../lib/clientDocuments.js';
const props=defineProps({client:{type:Object,required:true},document:{type:Object,default:null}});const emit=defineEmits(['close','saved','show-documents']);
const SOURCE_PAGE_SIZE=8;const loading=ref(true),saving=ref(false),action=ref(''),error=ref(''),saveMessage=ref(props.document?'Saved':'Not saved yet'),sources=ref([]),selectedSourceIds=ref([]),addedSourceIds=ref([]),expandedSourceId=ref(null),sourceQuery=ref(''),visibleSourceCount=ref(SOURCE_PAGE_SIZE),currentDocument=ref(props.document),previewUrl=ref(''),previewFrame=ref(null),baseline=ref('');
const form=reactive({title:props.document?.title||'',documentType:props.document?.documentType||'clinical_summary',recipient:props.document?.recipient||'',purpose:props.document?.purpose||'',periodStart:props.document?.periodStart||'',periodEnd:props.document?.periodEnd||'',body:props.document?.content?.body||''});
const selectedSources=computed(()=>sources.value.filter(source=>selectedSourceIds.value.includes(source.id)));const addableSelectedSources=computed(()=>selectedSources.value.filter(source=>!addedSourceIds.value.includes(source.id)));const filteredSources=computed(()=>{const query=sourceQuery.value.trim().toLowerCase();if(!query)return sources.value;return sources.value.filter(source=>`${formatDate(source.occurredAt)} ${source.notes||''}`.toLowerCase().includes(query));});const visibleSources=computed(()=>filteredSources.value.slice(0,visibleSourceCount.value));const hasMoreSources=computed(()=>visibleSources.value.length<filteredSources.value.length);const nextSourceCount=computed(()=>Math.min(SOURCE_PAGE_SIZE,filteredSources.value.length-visibleSources.value.length));const allVisibleSelected=computed(()=>visibleSources.value.length>0&&visibleSources.value.every(source=>selectedSourceIds.value.includes(source.id)));const finalised=computed(()=>currentDocument.value?.status==='completed');const dirty=computed(()=>!finalised.value&&baseline.value!==snapshot());
onMounted(async()=>{try{sources.value=await listDocumentSourceSessions(props.client.id);const ids=new Set((props.document?.sourceManifest||[]).filter(item=>item.kind==='session').map(item=>item.id));selectedSourceIds.value=sources.value.filter(source=>ids.has(source.id)).map(source=>source.id);addedSourceIds.value=[...selectedSourceIds.value];baseline.value=snapshot();}catch(e){console.error('Failed to load document sources:',e);error.value='Could not load completed session notes.';}finally{loading.value=false;}});onBeforeUnmount(closePreview);watch(finalised,value=>{if(value)closePreview();});
function sourceManifest(){return selectedSources.value.map(source=>({kind:'session',id:source.id,version:source.version,occurredAt:source.occurredAt}));}function changes(){return{title:form.title,documentType:form.documentType,recipient:form.recipient,purpose:form.purpose,periodStart:form.periodStart||null,periodEnd:form.periodEnd||null,content:{body:form.body},sourceManifest:sourceManifest()};}function snapshot(){return JSON.stringify(changes());}
function appendSources(){const pending=addableSelectedSources.value;if(!pending.length)return;const text=pending.map(source=>`Session ${formatDate(source.occurredAt)}\n${source.notes||''}`.trim()).join('\n\n');if(text)form.body=[form.body.trim(),text].filter(Boolean).join('\n\n');addedSourceIds.value=[...new Set([...addedSourceIds.value,...pending.map(source=>source.id)])];}
function toggleSourcePreview(id){expandedSourceId.value=expandedSourceId.value===id?null:id;}function toggleAllVisible(event){const ids=visibleSources.value.map(source=>source.id);if(event.target.checked)selectedSourceIds.value=[...new Set([...selectedSourceIds.value,...ids])];else selectedSourceIds.value=selectedSourceIds.value.filter(id=>!ids.includes(id));}function loadMoreSources(){visibleSourceCount.value+=SOURCE_PAGE_SIZE;}function resetSourceWindow(){visibleSourceCount.value=SOURCE_PAGE_SIZE;expandedSourceId.value=null;}
async function persistDraft(){currentDocument.value=currentDocument.value?await saveClientDocumentDraft(currentDocument.value,changes()):await createClientDocumentDraft({client:props.client,...changes()});baseline.value=snapshot();saveMessage.value=`Saved ${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})} to Client Documents`;emit('saved',currentDocument.value);return currentDocument.value;}
async function saveDraft(){if(saving.value||!form.title.trim())return;saving.value=true;action.value='save';error.value='';try{await persistDraft();}catch(e){console.error('Failed to save document draft:',e);error.value=e.code==='DOCUMENT_CONFLICT'?e.message:'Could not save this document draft.';}finally{saving.value=false;action.value='';}}
async function previewDocument(){if(saving.value)return;saving.value=true;action.value='preview';error.value='';try{const draft=await persistDraft();const blob=await previewClientDocument(draft);closePreview();previewUrl.value=URL.createObjectURL(blob);}catch(e){console.error('Failed to preview document:',e);error.value=e.code==='DOCUMENT_CONFLICT'?e.message:(e.message||'Could not preview this document.');}finally{saving.value=false;action.value='';}}
async function finaliseDocument(){if(saving.value||!form.body.trim())return;if(!window.confirm('Finalise this document? The saved PDF will become read-only.'))return;saving.value=true;action.value='finalise';error.value='';try{const draft=await persistDraft();currentDocument.value=await finaliseClientDocument(draft);baseline.value=snapshot();saveMessage.value='Finalised and saved to Client Documents';emit('saved',currentDocument.value);}catch(e){console.error('Failed to finalise document:',e);error.value=e.code==='DOCUMENT_CONFLICT'?e.message:(e.message||'Could not finalise this document.');}finally{saving.value=false;action.value='';}}
async function downloadFinalised(){try{await downloadClientDocument(currentDocument.value);}catch(e){error.value=e.message||'Could not download this document.';}}
function requestClose(){if(saving.value)return;if(dirty.value&&!window.confirm('You have unsaved changes. Close without saving them?'))return;emit('close');}function printPreview(){previewFrame.value?.contentWindow?.print();}function closePreview(){if(previewUrl.value){URL.revokeObjectURL(previewUrl.value);previewUrl.value='';}}function formatDate(value){return value?new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Date unavailable';}function formatDateTime(value){return value?new Date(value).toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'just now';}
</script>
